<template><section class="migration-cohort"><h3>Move families into AuricWell</h3><p>Select a small provider cohort and review the family recipients. Each account receives one invitation for the selected linked clients. Existing passwords remain unchanged.</p><label>Cohort name<input v-model="cohort" maxlength="120" placeholder="Provider name · first group"></label><fieldset><legend>Clients in this group</legend><label v-for="c in clients" :key="c.id"><input type="checkbox" v-model="selected" :value="c.id"> {{ c.name }}</label></fieldset><button :disabled="busy||!selected.length" @click="prepareAccounts">Prepare saved guardian accounts — no email</button><p v-if="prepared" role="status">{{ prepared }}</p><button :disabled="busy||!selected.length||!cohort.trim()" @click="preview">Review invitations</button><p v-if="error" role="alert">{{ error }}</p><template v-if="review"><p v-if="!review.launchEnabled">Invitations are prepared for review. Sending will be available after rollout is enabled.</p><article v-for="r in review.recipients" :key="r.key"><strong>{{ r.name }}</strong><p>{{ r.email }} · {{ r.clients.length }} linked profile(s)</p><button :disabled="busy||!review.launchEnabled||sent.includes(r.key)" @click="send(r)">{{ sent.includes(r.key)?'Processed':'Send portal welcome' }}</button></article><p v-for="s in review.skipped" :key="s.clientId">{{ s.label }}: {{ s.reason }}</p></template></section></template>
<script setup>
import {computed,ref,watch} from 'vue';import api from '../../services/api';const props=defineProps({agencyId:Number,links:{type:Array,default:()=>[]}});const clients=computed(()=>[...new Map(props.links.map(l=>[Number(l.clientId),{id:Number(l.clientId),name:l.clientName}])).values()]);const prepared=ref('');const cohort=ref(''),selected=ref([]),review=ref(null),busy=ref(false),error=ref(''),sent=ref([]);let sequence=0;const payload=()=>({agencyId:props.agencyId,cohortLabel:cohort.value,clientIds:[...selected.value]});
async function prepareAccounts(){if(busy.value)return;const own=sequence;busy.value=true;error.value='';try{const r=await api.post('/portal-migration/staff/prepare-accounts',{...payload(),apply:true});if(own===sequence)prepared.value=`${r.data.results.filter(x=>x.prepared).length} guardian accounts prepared. No invitations sent. New contact-only links require access review before invitation.`;}catch(e){if(own===sequence)error.value=e.response?.data?.error?.message||'Account preparation failed.';}finally{busy.value=false;}}
async function preview(){if(busy.value)return;const own=sequence;busy.value=true;error.value='';try{const r=await api.post('/portal-migration/staff/preview',payload());if(own===sequence)review.value=r.data;}catch(e){if(own===sequence)error.value=e.response?.data?.error?.message||'Invitations could not be prepared.';}finally{busy.value=false;}}
async function send(r){if(busy.value)return;const own=sequence;busy.value=true;error.value='';try{const result=await api.post('/portal-migration/staff/invite',{...payload(),recipientKey:r.key});if(own===sequence){sent.value.push(r.key);if(result.data.delivery?.blocked||result.data.delivery?.skipped||result.data.delivery?.queued)error.value='The invitation was held by delivery or recipient settings; review the communication history.';}}catch(e){if(own===sequence)error.value=e.response?.data?.error?.message||'The invitation could not be sent.';}finally{busy.value=false;}}
watch(()=>[props.agencyId,cohort.value,...selected.value],()=>{sequence++;prepared.value='';review.value=null;sent.value=[];error.value='';});
</script>
<style scoped>.migration-cohort{padding:22px;border:1px solid var(--border,#dde5ef);border-radius:12px;margin:18px 0}.migration-cohort label{display:block;margin:10px 0}.migration-cohort input:not([type=checkbox]){padding:10px;width:100%;box-sizing:border-box}.migration-cohort fieldset{max-height:250px;overflow:auto;margin:16px 0;border:1px solid #cad9e6}.migration-cohort article{padding:14px;border-top:1px solid #dce5ef}.migration-cohort p{line-height:1.6}.migration-cohort button{padding:10px 16px;border:1px solid #b8cada;border-radius:8px;background:#edf5fb;color:#17436f}.migration-cohort [role=alert]{color:#a12222}</style>
